{
  "score": 6,
  "issues": [
    {
      "file": "evalmerge/parsers.py",
      "lines": "203-204",
      "severity": "high",
      "description": "Format B assumes metrics is a dict, so truthy malformed values crash ingest with AttributeError instead of producing a warning."
    },
    {
      "file": "evalmerge/parsers.py",
      "lines": "254",
      "severity": "high",
      "description": "Malformed Format C XML is not caught, so ET.ParseError aborts the entire ingest instead of recording a malformed_row warning."
    },
    {
      "file": "evalmerge/parsers.py",
      "lines": "205, 232",
      "severity": "high",
      "description": "Non-finite JSON scores such as NaN are accepted as numeric and can crash SQLite insertion or store invalid score data."
    },
    {
      "file": "evalmerge/normalize.py",
      "lines": "89-95",
      "severity": "high",
      "description": "Score clamping does not reject NaN or infinity, so invalid floats bypass validation."
