    {
      "file": "evalmerge/parsers.py",
      "lines": "105-109",
      "severity": "low",
      "description": "CSV over-split recovery uses raw comma splitting, which can corrupt rows if earlier fields are valid quoted CSV containing commas."
    }
  ],
